import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
import QRCode from "https://esm.sh/qrcode@1.5.3";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function money(value) {
  return Number(value || 0).toFixed(2);
}

function qty(value) {
  return Number(value || 0).toFixed(3);
}

function formatDate(value) {
  if (!value) return "";
  return new Date(value).toLocaleDateString("en-GB");
}

function formatDateTime(value) {
  if (!value) return "";
  return new Date(value).toLocaleString("en-GB");
}

function fiscalPayload(header) {
  if (header.fiscalVerificationUrl) return header.fiscalVerificationUrl;

  return [
    "FISCAL_RECEIPT",
    `FISCAL_NO=${header.fiscalNumber || header.fiscal_number || header.documentNumber || ""}`,
    `INTERNAL_NO=${header.documentNumber || ""}`,
    `DATE=${header.documentDate || ""}`,
    `TOTAL=${header.totalAmount || ""}`,
    `CURRENCY=${header.currencyCode || "EUR"}`,
    `ZKI=${header.zki || ""}`,
    `JIR=${header.jir || ""}`
  ].join("|");
}

function paymentPayload(header) {
  if (header.paymentQrPayload) return header.paymentQrPayload;
  if (header.paymentUrl) return header.paymentUrl;

  return [
    "PAYMENT",
    `REFERENCE=${header.paymentReference || header.documentNumber || ""}`,
    `AMOUNT=${money(header.openAmount || header.totalAmount || 0)}`,
    `CURRENCY=${header.currencyCode || "EUR"}`,
    `PAYEE=${header.companyName || ""}`,
    `IBAN=${header.companyIban || header.iban || ""}`
  ].join("|");
}

function returnPayload(header) {
  return [
    "POS_RETURN",
    `DOCUMENT_ID=${header.documentId || header.id || ""}`,
    `FISCAL_NO=${header.fiscalNumber || header.fiscal_number || ""}`,
    `DOCUMENT_NO=${header.documentNumber || ""}`,
    `DATE=${header.documentDate || ""}`,
    `WAREHOUSE_ID=${header.warehouseId || ""}`,
    `CUSTOMER_ID=${header.customerId || header.partnerId || ""}`,
    `TOTAL=${header.totalAmount || ""}`,
    `CURRENCY=${header.currencyCode || "EUR"}`
  ].join("|");
}

function returnBarcodeValue(header) {
  return String(
    header.returnReference ||
    header.fiscalNumber ||
    header.fiscal_number ||
    header.documentNumber ||
    ""
  ).replace(/[^A-Za-z0-9-]/g, "");
}

function App() {
  const data = appsmith.model || {};
  const header = data.header || {};
  const items = data.items || [];
  const taxes = data.taxes || [];

  const [fiscalQr, setFiscalQr] = React.useState("");
  const [paymentQr, setPaymentQr] = React.useState("");
  const barcodeRef = React.useRef(null);

  const documentKey = `${header.documentNumber || ""}-${header.fiscalNumber || ""}-${header.jir || ""}`;

  React.useEffect(() => {
    async function buildCodes() {
      if (!header.documentNumber) return;

      setFiscalQr(await QRCode.toDataURL(fiscalPayload(header), {
        margin: 1,
        width: 160,
        errorCorrectionLevel: "M"
      }));

      setPaymentQr(await QRCode.toDataURL(paymentPayload(header), {
        margin: 1,
        width: 160,
        errorCorrectionLevel: "M"
      }));
    }

    buildCodes();
  }, [documentKey]);

  React.useEffect(() => {
    const value = returnBarcodeValue(header);

    if (!value || !barcodeRef.current) return;

    JsBarcode(barcodeRef.current, value, {
      format: "CODE128",
      displayValue: true,
      fontSize: 12,
      height: 48,
      margin: 0
    });
  }, [documentKey]);

  const printReceipt = () => {
    window.print();
  };

  if (!header.documentNumber) {
    return (
      <div className="empty">
        <div>No receipt data available.</div>
      </div>
    );
  }

  return (
    <div className="page">
      <button className="print-button no-print" onClick={printReceipt}>
        Print receipt
      </button>

      <div className="receipt">
        <div className="top">
          {(header.companyLogoPath || header.company_logo_path) && (
            <img className="logo" src={header.companyLogoPath || header.company_logo_path} />
          )}

          <h1>{header.companyName || "Company"}</h1>

          <div className="company-details">
            {header.companyAddress && <div>{header.companyAddress}</div>}
            {(header.companyPostalCode || header.companyCity) && (
              <div>{header.companyPostalCode} {header.companyCity}</div>
            )}
            {header.companyTaxNumber && <div>Tax No: {header.companyTaxNumber}</div>}
            {header.companyRegistrationNumber && <div>Reg No: {header.companyRegistrationNumber}</div>}
            {header.companyEmail && <div>{header.companyEmail}</div>}
            {header.companyPhone && <div>{header.companyPhone}</div>}
          </div>
        </div>

        <div className="divider" />

        <div className="receipt-title">
          <div>
            <span>Fiscal Receipt</span>
            <strong>{header.fiscalNumber || header.fiscal_number || header.documentNumber}</strong>
            <small>Internal No: {header.documentNumber}</small>
          </div>
          <div className="status">{header.status || "POSTED"}</div>
        </div>

        <div className="divider" />

        <div className="info-grid">
          <div>
            <label>Date</label>
            <span>{formatDate(header.documentDate)}</span>
          </div>
          <div>
            <label>Created</label>
            <span>{formatDateTime(header.createdAt || header.created_at)}</span>
          </div>
          <div>
            <label>Warehouse</label>
            <span>{header.warehouseName || "-"}</span>
          </div>
          <div>
            <label>Cashier</label>
            <span>{header.cashier || header.createdBy || appsmith.model.username || "-"}</span>
          </div>
          <div>
            <label>Payment</label>
            <span>{header.paymentMethod || "-"}</span>
          </div>
          <div>
            <label>Reference</label>
            <span>{header.paymentReference || header.documentNumber || "-"}</span>
          </div>
        </div>

        {(header.partnerName || header.customerName || header.partnerCode) && (
          <>
            <div className="divider" />
            <div className="partner-box">
              <label>Customer</label>
              <strong>{header.partnerName || header.customerName}</strong>
              {header.partnerCode && <span>{header.partnerCode}</span>}
            </div>
          </>
        )}

        <div className="divider" />

        <table>
          <thead>
            <tr>
              <th>Item</th>
              <th className="num">Qty</th>
              <th className="num">Price</th>
              <th className="num">Total</th>
            </tr>
          </thead>
          <tbody>
            {items.map((item, index) => (
              <tr key={index}>
                <td>
                  <strong>{item.description || item.productName || item.product || "Item"}</strong>
                  {(item.productCode || item.barcode) && (
                    <small>
                      {item.productCode || ""}
                      {item.productCode && item.barcode ? " / " : ""}
                      {item.barcode || ""}
                    </small>
                  )}
                </td>
                <td className="num">{qty(item.quantity)}</td>
                <td className="num">{money(item.unitPrice)}</td>
                <td className="num">{money(item.lineTotal)}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="divider" />

        <div className="totals">
          <div>
            <span>Subtotal</span>
            <strong>{money(header.subtotalAmount)} {header.currencyCode || "EUR"}</strong>
          </div>
          <div>
            <span>Discount</span>
            <strong>{money(header.discountAmount)} {header.currencyCode || "EUR"}</strong>
          </div>
          <div>
            <span>Tax</span>
            <strong>{money(header.taxAmount)} {header.currencyCode || "EUR"}</strong>
          </div>
          <div className="grand">
            <span>Total</span>
            <strong>{money(header.totalAmount)} {header.currencyCode || "EUR"}</strong>
          </div>
          <div>
            <span>Paid</span>
            <strong>{money(header.paidAmount || header.totalAmount)} {header.currencyCode || "EUR"}</strong>
          </div>
        </div>

        {taxes.length > 0 && (
          <>
            <div className="divider" />
            <table>
              <thead>
                <tr>
                  <th>Tax %</th>
                  <th className="num">Base</th>
                  <th className="num">Tax</th>
                </tr>
              </thead>
              <tbody>
                {taxes.map((tax, index) => (
                  <tr key={index}>
                    <td>{money(tax.taxRate)}%</td>
                    <td className="num">{money(tax.taxableAmount)}</td>
                    <td className="num">{money(tax.taxAmount)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

        <div className="divider" />

        <div className="fiscal">
          <div>
            <label>Fiscal Number</label>
            <span>{header.fiscalNumber || header.fiscal_number || "-"}</span>
          </div>
          <div>
            <label>ZKI</label>
            <span>{header.zki || "-"}</span>
          </div>
          <div>
            <label>JIR</label>
            <span>{header.jir || "-"}</span>
          </div>
        </div>

        <div className="divider" />

        <div className="qr-grid">
          <div className="qr-box">
            {fiscalQr && <img src={fiscalQr} />}
            <div>Fiscal verification</div>
          </div>
          <div className="qr-box">
            {paymentQr && <img src={paymentQr} />}
            <div>Payment code</div>
          </div>
        </div>

        <div className="barcode-box">
          <svg ref={barcodeRef}></svg>
          <div>Scan for return / reference lookup</div>
        </div>

        {(header.note || header.internalNote) && (
          <>
            <div className="divider" />
            <div className="note">
              <label>Note</label>
              <div>{header.note || header.internalNote}</div>
            </div>
          </>
        )}

        <div className="footer">
          <strong>Thank you for your purchase!</strong>
          <span>Please keep this receipt as proof of purchase.</span>
        </div>
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
